  const data={severity,category,urls:urls.join('\n'),evidence:advice+detail+' Found on '+urls.length+' of '+items.length+' crawled pages.',confidence:'high',estimated_clicks:0,effort:severity==='critical'?3:severity==='high'?2:1,fix_route,issue_type:'crawl:'+key,audit_id:record.id,affected:urls.length};
  const prev=open.find(r=>r.data.issue_type==='crawl:'+key);
