// Page and query movement for the dashboard, stored per client in settings (not as records).
async function saveSearchInsights(env,client,token,ranges){const q=(dimensions,[startDate,endDate],rowLimit=500)=>jsonRequest('https://www.googleapis.com/webmasters/v3/sites/'+encodeURIComponent(client.data.gsc_property)+'/searchAnalytics/query',{method:'POST',headers:{Authorization:'Bearer '+token,'Content-Type':'application/json'},body:JSON.stringify({startDate,endDate,dimensions,rowLimit,dataState:'final'})}).then(d=>d.rows||[]);
 const [cur,prev,queries]=await Promise.all([q(['page'],ranges.current),q(['page'],ranges.previous),q(['query'],ranges.current)]);
 const merge=rs=>{const out=new Map();for(const r of rs){const url=r.keys[0].split('#')[0],o=out.get(url)||{clicks:0,impressions:0,w:0};o.clicks+=r.clicks;o.impressions+=r.impressions;o.w+=r.position*r.impressions;out.set(url,o)}for(const o of out.values())o.position=o.w/Math.max(1,o.impressions);return out},before=merge(prev),after=merge(cur);
 const pages=[...new Set([...before.keys(),...after.keys()])].map(url=>{const a=after.get(url),b=before.get(url);return{url,clicks:a?.clicks||0,prev_clicks:b?.clicks||0,change:(a?.clicks||0)-(b?.clicks||0),impressions:a?.impressions||0,position:a?Math.round(a.position*10)/10:null,prev_position:b?Math.round(b.position*10)/10:null}});
 const striking=queries.filter(r=>r.position>=4&&r.position<=20&&r.impressions>=10).sort((x,y)=>y.impressions-x.impressions).slice(0,9).map(r=>({query:r.keys[0],impressions:r.impressions,clicks:r.clicks,position:Math.round(r.position*10)/10,ctr:r.ctr}));
 const insights={synced_at:now(),current:ranges.current,previous:ranges.previous,pages_up:pages.filter(p=>p.change>0).sort((x,y)=>y.change-x.change).slice(0,6),pages_down:pages.filter(p=>p.change<0).sort((x,y)=>x.change-y.change).slice(0,6),striking,top_queries:queries.slice().sort((x,y)=>y.clicks-x.clicks).slice(0,6).map(r=>({query:r.keys[0],clicks:r.clicks,impressions:r.impressions,position:Math.round(r.position*10)/10}))};
 const old=await one(env,'SELECT value FROM settings WHERE key=?','gsc_insights:'+client.id),kept=old?JSON.parse(old.value):{};await run(env,'INSERT INTO settings(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value','gsc_insights:'+client.id,JSON.stringify({...insights,cannibal:kept.cannibal,cannibal_at:kept.cannibal_at}))}

// Intent from simple wording rules; labelled as automatic so people can correct it.
function guessIntent(query,client){const q=query.toLowerCase(),brand=[client.name,...(String(client.data.brand_terms||'').split(','))].map(b=>b.trim().toLowerCase()).filter(b=>b.length>2);let host='';try{host=new URL(client.url).hostname.replace(/^www\./,'').split('.')[0]}catch{}
 if(brand.some(b=>q.includes(b))||(host.length>3&&q.replace(/\s/g,'').includes(host)))return'Navigational';
 if(/\b(price|prices|cost|costs|fee|fees|buy|order|near me|book|booking|appointment|cheap|offer|emi|discount|clinic|hire)\b/.test(q))return'Transactional';
 if(/\b(best|vs|versus|review|reviews|compare|comparison|top|alternative|alternatives)\b/.test(q))return'Commercial';
 return'Informational'}
// Question detection: keywords starting with or containing question words.
function isQuestion(query){return /^(who|what|where|when|why|how|can|is|are|do|does|did|will|should|which|whose|has|have|was|were|could|would|may|might)\b/i.test(query.trim())||/\?$/.test(query.trim())}
// Keyword category for the 6 research buckets. competitor_url is set externally.
function guessKeywordCategory(query,volume,intent,competitor){if(competitor)return'Competitor';if(isQuestion(query))return'Question';if(intent==='Commercial'||intent==='Transactional')return'Commercial';if((Number(volume)||0)>=1000)return'High Volume';if(intent==='Informational')return'Informational';return'Most Searched'}
